param([string]$Project="backend/SanSo.Migrator.V6/SanSo.Migrator.V6.csproj")
$ErrorActionPreference="Stop";$xml=[xml](Get-Content -LiteralPath $Project -Raw -Encoding UTF8);$names=@($xml.Project.ItemGroup.None|Where-Object{$_.Link-like"Migrations/*"}|ForEach-Object{[string]$_.Link}|Sort-Object);if($names.Count-ne13){throw"MIGRATION_COUNT_INVALID:$($names.Count)"};for($i=0;$i-lt13;$i++){if(-not$names[$i].StartsWith(("Migrations/{0:D3}_"-f($i+1)),[StringComparison]::Ordinal)){throw"MIGRATION_SEQUENCE_INVALID:$($names[$i])"}};"MIGRATION_MANIFEST_V11_VERIFIED count=13 first=$($names[0]) last=$($names[-1])"
